import{_ as s,C as a,c as r,o as i,a3 as t,G as o}from"./chunks/framework.Dokpd4od.js";const q=JSON.parse('{"title":"Manage equipment","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/maintenance/equipment/manage-equipment.md","filePath":"master/supply-chain/maintenance/equipment/manage-equipment.md","lastUpdated":1791902625000}'),l={name:"master/supply-chain/maintenance/equipment/manage-equipment.md"};function u(h,e,g,c,d,p){const n=a("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="manage-equipment" tabindex="-1">Manage equipment <a class="header-anchor" href="#manage-equipment" aria-label="Permalink to &quot;Manage equipment&quot;">​</a></h1><p>The equipment list shows every item you maintain. Use it to find a machine, see who is responsible and clean up items you no longer use. Tabs, filters, grouping and search help you narrow a long list quickly.</p><blockquote><p><strong>In simple words:</strong> The list is your asset register. Search it, slice it, and archive items you stop using.</p></blockquote><p>Path: <code>Maintenance → Equipment</code></p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list opens on the <strong>My Equipment</strong> tab. It shows only items where you are the <strong>Owner</strong>, so it can be empty. Click <strong>Default</strong> to see all equipment.</p>',6)),o(n,{src:"/images1/maintenance/eq_list_default.png",alt:"Equipment list table on the Default tab with four equipment rows including Hydraulic Press 200T"}),e[1]||(e[1]=t('<h3 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h3><ul><li><strong>Default:</strong> All active equipment.</li><li><strong>My Equipment:</strong> Items where you are the Owner. This tab is selected when the page opens.</li><li><strong>Assigned:</strong> Items that have an Owner.</li><li><strong>Unassigned:</strong> Items with no Owner.</li><li><strong>Archived:</strong> Items you archived.</li></ul>',2)),o(n,{src:"/images1/maintenance/eq_list_tabs.png",alt:"Equipment list tab bar with Default, My Equipment, Assigned, Unassigned and Archived"}),e[2]||(e[2]=t('<h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><p>The list shows <strong>Equipment Name</strong>, <strong>Owner</strong>, <strong>Serial Number</strong>, <strong>Technician</strong>, <strong>Equipment Category</strong> and <strong>Company</strong>. Use the column toggle to add <strong>Created At</strong>.</p><h2 id="find-equipment" tabindex="-1">Find equipment <a class="header-anchor" href="#find-equipment" aria-label="Permalink to &quot;Find equipment&quot;">​</a></h2><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><p>Type in the search box. It matches the equipment name and the serial number. For example, search <code>HP-200-2026-001</code>.</p>',5)),o(n,{src:"/images1/maintenance/eq_list_search.png",alt:"Search box with the serial number HP-200-2026-001, an Active filters Search chip and one matching row"}),e[3]||(e[3]=t('<h3 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h3><ol><li>Click the filter icon.</li><li>Choose <strong>Equipment Category</strong>, <strong>Maintenance Team</strong> or <strong>Technician</strong>.</li><li>Click <strong>Apply filters</strong>. Click <strong>Reset</strong> to clear them.</li></ol>',2)),o(n,{src:"/images1/maintenance/eq_list_filters.png",alt:"Filter panel with Equipment Category set to Packaging Machines"}),e[4]||(e[4]=t('<h3 id="group-by" tabindex="-1">Group by <a class="header-anchor" href="#group-by" aria-label="Permalink to &quot;Group by&quot;">​</a></h3><p>Open <strong>Group by</strong> and choose <strong>Technician</strong>, <strong>Equipment Category</strong>, <strong>Owner</strong> or <strong>Vendor</strong>. Set the direction to <strong>Ascending</strong> or <strong>Descending</strong>.</p>',2)),o(n,{src:"/images1/maintenance/eq_list_group_by.png",alt:"Equipment list grouped by Equipment Category"}),e[5]||(e[5]=t('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Use the saved views menu next to the tabs to pin your favourite tabs, or to add your own view with <strong>Add New</strong>.</p></div><h2 id="row-actions" tabindex="-1">Row actions <a class="header-anchor" href="#row-actions" aria-label="Permalink to &quot;Row actions&quot;">​</a></h2><p>Click a row to open its <strong>View</strong> page. Each row has these actions:</p><ul><li><strong>View:</strong> Opens the read-only page.</li><li><strong>Edit:</strong> Opens the form so you can change values.</li><li><strong>Delete:</strong> Archives the equipment.</li></ul><h2 id="archive-restore-and-delete" tabindex="-1">Archive, restore and delete <a class="header-anchor" href="#archive-restore-and-delete" aria-label="Permalink to &quot;Archive, restore and delete&quot;">​</a></h2><p>Archiving hides equipment that you no longer use, but keeps its history.</p><ol><li>On the <strong>Hydraulic Press 200T</strong> row, click <strong>Delete</strong>.</li><li>A window titled &quot;Delete Hydraulic Press 200T&quot; asks &quot;Are you sure you would like to do this?&quot;. Click <strong>Delete</strong>. Click <strong>Cancel</strong> to stop.</li><li>Open the <strong>Archived</strong> tab. The item is listed there.</li></ol>',7)),o(n,{src:"/images1/maintenance/eq_list_archived.png",alt:"Archived tab showing the single archived equipment, Hydraulic Press 200T, with Restore and Force delete links in its row"}),e[6]||(e[6]=t('<p>On the <strong>Archived</strong> tab, each row shows two links:</p><ul><li><strong>Restore:</strong> Opens a window titled &quot;Restore Hydraulic Press 200T&quot; with <strong>Cancel</strong> and <strong>Restore</strong>. After you confirm, the message &quot;Equipment restored&quot; appears with &quot;The equipment has been restored successfully.&quot;</li><li><strong>Force delete:</strong> Removes the item for good. The message &quot;Equipment deleted&quot; appears.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Force delete cannot be undone. If a request or other record still uses the equipment, deletion stops with &quot;Equipment could not be deleted&quot;. Archive the item instead.</p></div><h3 id="bulk-actions" tabindex="-1">Bulk actions <a class="header-anchor" href="#bulk-actions" aria-label="Permalink to &quot;Bulk actions&quot;">​</a></h3><p>Tick one or more rows to open <strong>Bulk actions</strong>. You can choose <strong>Delete selected</strong> (archive), <strong>Restore selected</strong> or <strong>Force delete selected</strong>. Use <strong>Select all</strong> to tick every row on the page.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./add-equipment.html">Add equipment</a></li><li><a href="./">Equipment overview</a></li><li><a href="./../requests/request-list.html">Request list</a></li></ul>',7))])}const _=s(l,[["render",u]]);export{q as __pageData,_ as default};
